                // extraction; the integrity check in `populate_result()` is
                // the sole arbiter of correctness once `Done` is reached.
                if let Some(e) = http_err {
                    if (*this).fail.is_none() && (*this).phase != Phase::Done {
                        (*this).fail = Some(e);
                    }
