        this: *mut Self,
        pipe_fd: Fd,
    ) -> Result<(), bun_core::Error> {
        // TODO(port): narrow error set
        log!("configureClient");
        let ipc_pipe: *mut uv::Pipe =
            bun_core::heap::into_raw(Box::new(bun_core::ffi::zeroed::<uv::Pipe>()));
        // SAFETY: ipc_pipe just allocated above.
