            s.title.as_bytes(),
            s.schedule.as_bytes(),
            s.abs_path.as_bytes(),
        ) {
            Ok(x) => x,
            Err(e) => {
                if e == TaskXmlError::TooManyTriggers {
                    s.set_err(format_args!(
                        "This cron expression requires too many triggers for Windows Task Scheduler (max 48). Simplify the expression or use fewer restricted fields."
                    ));
                } else {
