                // `ctx`. `run_event` may free the allocation, so pass the raw
                // pointer through — never form a `&mut` here whose protector
                // would span the dealloc.
                unsafe { DuplexUpgradeContext::run_event(p.cast::<DuplexUpgradeContext>()) };
